mapper.select:
select IFNULL(count(*),0) num from tb_screen_sum s LEFT JOIN tb_screen_collect c on s.collect_id=c.id LEFT JOIN tb_screen_ppd p on s.ppd_id=p.id
((c.outcome <> 0 and QUARTER(s.last_collect_time)=#{quarter}) or (p.outcome <> 0 and QUARTER(s.last_ppd_time)=#{quarter})) and s.person_id in
#{personId}
and s.screen_type=#{screenType} and s.year=#{year}

select id
from tb_screen_person

     and more_type & #{moreType} > 0
     and age>=#{leftAge}
     and screen_type=#{screenType}
     and year=#{year}

select id
from tb_screen_person

     and more_type & #{moreType} > 0
     and age BETWEEN #{leftAge} and #{rightAge}
     and screen_type=#{screenType}
     and year=#{year}

SELECT IFNULL(COUNT(*),0)
FROM tb_screen_sum s
         left join tb_screen_ppd p on s.ppd_id=p.id
WHERE ppd_id is not NULL and p.outcome=1
 and QUARTER(s.last_ppd_time)=#{quarter}
 and s.screen_type=#{screenType}
 and s.year=#{year}
and s.person_id in

        #{personId}

select IFNULL(COUNT(1),0)
FROM tb_screen_sum
WHERE ((chest_radiograph_id is not null  and QUARTER(last_chest_radiograph_time)=#{quarter} )
or (computed_tomography_id is not null  and QUARTER(last_computed_tomography_time)=#{quarter} ))
 and screen_type=#{screenType}
 and year=#{year}

select IFNULL(COUNT(*),0)
FROM tb_screen_sum s
LEFT JOIN tb_screen_chest_radiograph r on s.chest_radiograph_id=r.id
LEFT JOIN tb_screen_computed_tomography t on s.computed_tomography_id=t.id
WHERE (r.outcome <> 0  and QUARTER(s.last_chest_radiograph_time)=#{quarter} 
or t.outcome <> 0  and QUARTER(s.last_computed_tomography_time)=#{quarter} )
and s.screen_type=#{screenType}
 and s.year=#{year}
and s.person_id in

        #{personId}

select IFNULL(COUNT(*),0)
FROM tb_screen_sum s
LEFT JOIN tb_screen_collect c on s.collect_id=c.id
LEFT JOIN tb_screen_chest_radiograph r on s.chest_radiograph_id=r.id
LEFT JOIN tb_screen_computed_tomography t on s.computed_tomography_id=t.id
WHERE (
    (c.outcome is not null  and QUARTER(s.last_collect_time)=#{quarter} )
    or( t.outcome <> 0  and QUARTER(s.last_computed_tomography_time)=#{quarter} )
    or( r.outcome <>0  and QUARTER(s.last_chest_radiograph_time)=#{quarter} )
    ) and s.screen_type=#{screenType}
 and s.year=#{year}
and s.person_id in

        #{personId}

select IFNULL(COUNT(*),0)
FROM tb_screen_sum s
WHERE s.sputum_examination_id is not null and s.screen_type=#{screenType}
 and s.year=#{year}
 and QUARTER(s.last_sputum_examination_time)=#{quarter}
